"""Prueba RT configurable sobre BM SA dinamica validada. No cambia drivers."""
import argparse,hashlib,shutil
from pathlib import Path
EXPECTED='91ac6225771dc9fad5b3bfe4ce0564a460b9b16f'
SA_PATCHES=[('#define TEST_TRANSACTIONS           10240u', '#define TEST_TRANSACTIONS           1920u'), ('static bool is_test_command(const mil1553_transaction_t *t)', '\n/* Cobertura exacta por SA, WC y direccion. Memoria fija: 15360 bytes.\n * Actualizar solamente al finalizar cada mensaje (incluidos timeouts). */\nstatic uint32_t sa_started[2][30][32];\nstatic uint32_t sa_ok[2][30][32];\nstatic void sa_record(unsigned tr, unsigned sa, unsigned wc, bool valid)\n{\n    if (tr > 1u || sa < 1u || sa > 30u || wc < 1u || wc > 32u) return;\n    sa_started[tr][sa-1u][wc-1u]++;\n    if (valid) sa_ok[tr][sa-1u][wc-1u]++;\n}\nstatic void sa_print(void)\n{\n    unsigned covered=0u, all_ok=0u;\n    printf("\\n--- COBERTURA SA (OK / iniciadas) ---\\nSA | BC->RT | RT->BC\\n");\n    for (unsigned a=0; a<30u; a++) {\n        uint32_t n[2]={0}, k[2]={0};\n        for (unsigned t=0; t<2u; t++) for (unsigned w=0; w<32u; w++) {\n            uint32_t started=sa_started[t][a][w], ok=sa_ok[t][a][w];\n            n[t]+=started; k[t]+=ok;\n            if (started) covered++;\n            if (started && started==ok) all_ok++;\n        }\n        printf("%2u | %lu/%lu | %lu/%lu\\n", a+1u,\n            (unsigned long)k[0],(unsigned long)n[0],(unsigned long)k[1],(unsigned long)n[1]);\n    }\n    printf("Combinaciones SA/WC/TR observadas: %u/1920\\n",covered);\n    printf("Combinaciones SA/WC/TR sin fallos: %u/1920\\n",all_ok);\n    printf("\\n--- MATRIZ SA/WC (OK / iniciadas) ---\\nSA WC | BC->RT | RT->BC\\n");\n    for (unsigned a=0; a<30u; a++) for (unsigned w=0; w<32u; w++)\n        printf("%2u %2u | %lu/%lu | %lu/%lu\\n",a+1u,w+1u,\n            (unsigned long)sa_ok[0][a][w],(unsigned long)sa_started[0][a][w],\n            (unsigned long)sa_ok[1][a][w],(unsigned long)sa_started[1][a][w]);\n}\n\nstatic bool is_test_command(const mil1553_transaction_t *t)'), ('return t->rt_address == 20u && t->subaddress == 18u &&', 'return t->rt_address == 20u && t->subaddress >= 1u && t->subaddress <= 30u &&'), ('Solo para el ensayo RT20/SA18; otros mensajes mantienen', 'Solo para el ensayo RT20/SA1..30; otros mensajes mantienen'), ('        if (complete && t->valid && t->data_count == wc && t->status_seen)\n            test_wc_ok[tr][wc - 1u]++;', '        bool test_valid = complete && t->valid && t->data_count == wc && t->status_seen;\n        if (test_valid)\n            test_wc_ok[tr][wc - 1u]++;\n        sa_record(tr,t->subaddress,wc,test_valid);'), ('        "WC                   : 1..32\\n"', '        "SA                   : 1..30\\n"\n        "WC                   : 1..32\\n"'), ('                signature_print();', '                sa_print();\n                signature_print();')]
PATCHES=[('#define TEST_TRANSACTIONS           1920u', '#define TEST_TRANSACTIONS           12u\n#define TEST_RT_ADDRESS 7u\nstatic const unsigned test_rt[6]={TEST_RT_ADDRESS,20u,TEST_RT_ADDRESS,0u,TEST_RT_ADDRESS,30u};\nstatic const unsigned test_sa[6]={1u,5u,15u,18u,30u,30u};\nstatic const unsigned test_wc[6]={1u,4u,8u,16u,32u,32u};\n'), ('return t->rt_address == 20u && t->subaddress >= 1u && t->subaddress <= 30u &&', 'return t->rt_address <= 30u && t->subaddress >= 1u && t->subaddress <= 30u &&'), ('BUS_1553_STATUS_MAKE(20u, false)', 'BUS_1553_STATUS_MAKE(t->rt_address, false)'), ('        test_expected_words += wc;', '        test_expected_words += (tr==0u || t->rt_address==TEST_RT_ADDRESS) ? wc : 0u;'), ('static void finish_transaction(', 'static unsigned test_passes, test_silence_ok, test_reply_ok;\nstatic bool test_verdict[TEST_TRANSACTIONS];\n\nstatic void finish_transaction('), ('        sa_record(tr,t->subaddress,wc,test_valid);', '        sa_record(tr,t->subaddress,wc,test_valid);\n        bool expected_reply = t->rt_address == TEST_RT_ADDRESS;\n        bool quiet = !complete && t->valid && !t->status_seen &&\n                     t->data_count == (tr==0u ? wc : 0u);\n        bool scheduled = false;\n        if (t->index >= 1u && t->index <= TEST_TRANSACTIONS) {\n            unsigned pair=(t->index-1u)/2u;\n            scheduled=t->rt_address==test_rt[pair] && t->subaddress==test_sa[pair] &&\n                      wc==test_wc[pair] && tr==((t->index-1u)&1u);\n            test_verdict[t->index-1u]=scheduled && (expected_reply?test_valid:quiet);\n            if(test_verdict[t->index-1u]) {\n                test_passes++;\n                if(expected_reply)test_reply_ok++;else test_silence_ok++;\n            }\n        }'), ('            transaction.valid =\n                false;\n\n            transaction.sequence_ok =\n                false;\n\n\n            /* Guardar transaccion invalida en RAM. */', '            /* finish_transaction clasifica el silencio esperado antes de marcar\n             * el timeout como transaccion incompleta. Mantener contadores brutos. */\n            /* Guardar transaccion invalida en RAM. */'), ('        "SA                   : 1..30\\n"', '        "RT activo esperado   : 7 (otros destinos: silencio)\\n"\n        "SA                   : 1..30\\n"'), ('                sa_print();\n                signature_print();', '                printf("\\n--- RESULTADO ENSAYO RT ---\\nRespuestas validas: %u/6\\nSilencios esperados OK: %u/6\\nResultados conformes: %u/12\\n",test_reply_ok,test_silence_ok,test_passes);\n                for(unsigned i=0;i<TEST_TRANSACTIONS;i++)\n                    printf("ENSAYO TX %u: %s\\n",i+1u,test_verdict[i]?"OK":"BAD");\n                signature_print();')]
def blob(b):return hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()
def apply(s,patches):
    for a,b in patches:
        if s.count(a)!=1:raise ValueError("Ancla no coincide: "+repr(a[:150]))
        s=s.replace(a,b,1)
    return s
def transform(s):
    if blob(s.encode())==EXPECTED:
        s=apply(s,SA_PATCHES)
    else:
        original=apply(s,[(b,a) for a,b in reversed(SA_PATCHES)])
        if blob(original.encode())!=EXPECTED:raise ValueError("main.c distinto de base validada")
    return apply(s,PATCHES)
def main():
    p=argparse.ArgumentParser();p.add_argument("root",nargs="?",default=".");p.add_argument("--check",action="store_true");a=p.parse_args()
    f=Path(a.root).resolve()/"main.c"
    try:
        raw=f.read_bytes();s=transform(raw.replace(b"\r\n",b"\n").decode())
        if a.check:print("OK: base y anclas verificadas; sin cambios");return
        backup=f.with_name("main_SA_validado.c.bak")
        if backup.exists():raise ValueError("Backup existente: "+str(backup))
        shutil.copy2(f,backup);tmp=f.with_name("main_rt.tmp");tmp.write_bytes(s.encode());tmp.replace(f)
        print("BM actualizado; backup:",backup)
    except (ValueError,OSError) as e:raise SystemExit("ABORTADO: "+str(e))
if __name__=="__main__":main()
